using System.Windows;using OncaPDV.Application;using OncaPDV.Infrastructure;namespace OncaPDV.Desktop;public partial class DocumentsWindow:Window{private readonly AdvancedOperationsService _ops;private readonly PosWorkflow _workflow;private readonly OperationalService _reports;public bool CartChanged{get;private set;}public DocumentsWindow(OncaDatabase db,PosWorkflow workflow){_ops=new(db);_reports=new(db,AppServices.Paths);_workflow=workflow;InitializeComponent();Loaded+=async(_,_)=>await Refresh();}private async Task Refresh(){Quotes.ItemsSource=await _ops.QuotesAsync();Fiscal.ItemsSource=await _ops.FiscalDraftsAsync();}private async void OpenQuote_Click(object s,RoutedEventArgs e){if(Quotes.SelectedItem is not QuoteView q)return;await _workflow.ReplaceCartAsync(await _ops.LoadQuoteAsync(q.Id));CartChanged=true;DialogResult=true;}private async void ConvertQuote_Click(object s,RoutedEventArgs e){if(Quotes.SelectedItem is not QuoteView q)return;await _ops.MarkQuoteConvertedAsync(q.Id);await Refresh();}private async void QuotePdf_Click(object s,RoutedEventArgs e){if(Quotes.SelectedItem is not QuoteView q)return;var file=await _reports.QuotePdfAsync(q,await _ops.QuoteItemsAsync(q.Id));MessageBox.Show($"Orçamento gerado: {file}");}
private async void QuoteWhatsApp_Click(object s,RoutedEventArgs e){if(Quotes.SelectedItem is not QuoteView q)return;var file=await _reports.QuotePdfAsync(q,await _ops.QuoteItemsAsync(q.Id));var text=Uri.EscapeDataString($"Onça Produtos de Limpeza - Orçamento {q.Number:000000}\nCliente: {q.Customer}\nTotal: {q.Total:C}\nArquivo: {file}");try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo($"https://wa.me/?text={text}"){UseShellExecute=true});}catch{Clipboard.SetText(file);MessageBox.Show("Caminho do PDF copiado.");}}
private async void Pending_Click(object s,RoutedEventArgs e){if(Fiscal.SelectedItem is not FiscalDraftView d)return;await _ops.MarkFiscalPendingAsync(d.Id);await Refresh();MessageBox.Show("Rascunho preparado para futura emissão fiscal.");}}
